@startuml

class Airline {
  + ID : int
}

class Airport {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : datetime
  + ArrivalTime : datetime
}

class Aircraft {
  + Type : string
  + IsWorking : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class AircraftType {
  + Name : string
}

class PilotRoleRequirement {
  + Role : string
  + RequiredCount : int
}

Airline "1" -- "*" Flight
Airline "1" -- "*" Aircraft
Flight "0..*" -- "1" Airport : departure
Flight "0..*" -- "1" Airport : arrival
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1..2" Pilot : co-pilot
Flight "0..*" -- "1" Aircraft
Aircraft "*" -- "1" AircraftType
AircraftType "1" -- "*" PilotRoleRequirement

@enduml

